from pathlib import Path
from decimal import Decimal,ROUND_HALF_UP
import csv,json,hashlib,sys
B=Path(__file__).resolve().parents[1];P=B/'results';assert len(sys.argv)==2, 'Supply a new output directory';O=Path(sys.argv[1]);assert not O.exists();O.mkdir(parents=True)
def read(name):
 with (P/(name+'.csv')).open(newline='') as f:return list(csv.DictReader(f))
def num(x,places=5,factor=1):return format((Decimal(x)*factor).quantize(Decimal(1).scaleb(-places),rounding=ROUND_HALF_UP),f'.{places}f')
def ci(r,places=5,value='optimism_corrected',factor=1):return f"{num(r[value],places,factor)} ({num(r['ci_lower'],places,factor)} to {num(r['ci_upper'],places,factor)})"
written=[]
def write(name,header,rows,sources,note):
 path=O/(name+'.csv')
 with path.open('w',newline='') as f:w=csv.writer(f);w.writerow(header);w.writerows(rows)
 written.append({'file':path.name,'sha256':hashlib.sha256(path.read_bytes()).hexdigest(),'row_count':len(rows),'sources':[{'file':s+'.csv','sha256':hashlib.sha256((P/(s+'.csv')).read_bytes()).hexdigest()} for s in sources],'note':note})
flow_labels={'total':'Valid 2010 grip assessment, all baseline participants','included':'Included in the analytical cohort','death_before_2014':'Documented death before calendar 2014','unmatched_tracker':'No matched Tracker record','documented_death_2014_2015_without_core':'Documented death in 2014–2015 without a Core interview','no_core_interview':'No qualifying 2014 Core interview','physical_measure_ineligible':'Ineligible for physical measurement','not_scheduled_for_2014_physical_measures':'Not scheduled for 2014 physical measurements','documented_unable':'Documented inability to complete grip measurement','no_valid_grip_or_other_exclusion':'No valid grip or another analytical exclusion'}
flow=read('selection_flow');write('tableS11_selection_flow',['Selection category','Count, rounded to tens'],[[flow_labels[r['metric']],r['count_rounded_10']] for r in flow],['selection_flow'],'Counts rounded to tens. Suppression may be complementary; do not infer suppressed counts or sum displayed values as exact totals. Exact analytical N is6307. All valid2010grip participants include people outside later age/eligibility criteria. Death categories are calendar-based and do not establish individual interwave timing.')
cont=read('selection_continuous');cr={(r['variable'],r['group']):r for r in cont};srh=read('selection_srh');sk={(r['metric'],r['group']):r for r in srh};data=[]
for v,label in [('age','Age in2010, years, mean±SD'),('grip','Maximum grip in2010, kg, mean±SD')]:
 inc,exc=cr[v,'included'],cr[v,'excluded'];data.append([label,f"{num(inc['mean'],1)} ± {num(inc['sd'],1)}",f"{num(exc['mean'],1)} ± {num(exc['sd'],1)}",num(inc['smd_included_minus_excluded'],3)])
for k,label in [('total','Total, rounded'),('srh_1','2010 SRH: excellent'),('srh_2','2010 SRH: very good'),('srh_3','2010 SRH: good'),('srh_4','2010 SRH: fair'),('srh_5','2010 SRH: poor'),('missing_srh','2010 SRH: missing')]:data.append([label,sk[k,'included']['count_rounded_10'],sk[k,'excluded']['count_rounded_10'],'—'])
sex=read('a1_sex_20261021/selection_sex');sx={(r['metric'],r['group']):r['count_rounded_10'] for r in sex}
assert len(sex)==len(sx)==8 and sx['total','included']=='6310' and sx['total','excluded']=='2380'
sexrows=[[label,sx[k,'included'],sx[k,'excluded'],'—'] for k,label in [('male','Recorded sex: male'),('female','Recorded sex: female'),('missing_or_invalid','Recorded sex: missing or invalid')]]
data[3:3]=sexrows
write('tableS12_selection_characteristics',['2010 characteristic','Included','Excluded','SMD, included−excluded'],data,['selection_continuous','selection_srh','a1_sex_20261021/selection_sex'],'SD=sample standard deviation; SMD=standardized mean difference using the square root of the unweighted average of the two group variances; SRH=self-rated health in2010. Available age/grip denominators are rounded6310/2380. Categorical values are rounded counts with complementary suppression; no percentages are reconstructed. Recorded sex uses Tracker codes1/2; missing or invalid includes unmatched Tracker records. Suppressed sex cells remain suppressed. No selection-bias direction can be inferred.')
v=read('validation');vk={(r['metric'],r['group'],r['target']):r for r in v}
model_labels={'covariates':'Covariates only','current':'Covariates + current grip','prior':'Covariates + current and prior grip','joint':'Covariates + current and prior grip + joint interaction','current_sex':'Current-grip model + sex×current-grip interaction','prior_sex':'Both-grip model + sex×both-grip interactions','current_no_srh':'Current-grip model without SRH','prior_no_srh':'Both-grip model without SRH'}
contrast_labels={'current_vs_covariates':'Current-grip model − covariates only','prior_vs_current':'Both-grip model − current-grip model','joint_vs_current':'Joint interaction model − current-grip model','joint_vs_additive':'Joint interaction model − additive both-grip model','sex_current_vs_current':'Sex×current model − current-grip model','sex_prior_vs_sex_current':'Sex×both-grip model − sex×current model','sex_prior_vs_additive':'Sex×both-grip model − additive both-grip model','prior_vs_current_no_srh':'Both-grip − current-grip model, without SRH'}
data=[[label,ci(vk['auc','all',key],4),ci(vk['brier','all',key],4)] for key,label in model_labels.items()]+[[label,ci(vk['auc','all',key],5),ci(vk['brier','all',key],5)] for key,label in contrast_labels.items()]
write('tableS13_additional_validation',['Model or added−reference comparison','Corrected AUC (95%CI)','Corrected Brier score (95%CI)'],data,['validation','validation_attempts'],'AUC=area under the receiver operating characteristic curve; SRH=self-rated health; CI=confidence interval. Separate revision run, seed20261019, eight fixed formulas,200outer×50inner household bootstrap, same6307completecases. First8rows are model levels, last8paired differences. PositiveAUC/negativeBrier differences favor added model. Percentile intervals use nested corrected resamples. All reported rows have200valid outer/nested values. Original primary Table2 is a different bootstrap run. Full5metric×3group×16target=240rows remain in validation.csv. Fit successes do not prove every inner-group metric finite.')
lr=read('likelihood');write('tableS14_nested_fit',['Added−reference comparison','LR χ²','Added df','ΔAIC'],[[contrast_labels[r['contrast']],num(r['lr_chisq'],2),r['df'],num(r['delta_aic'],2)] for r in lr],['likelihood'],'LR=likelihood ratio; df=degrees of freedom; AIC=Akaike information criterion. ΔAIC=added−reference; negative favors added. These are apparent nested fit comparisons, not validated performance or proof of clinical usefulness. The joint interaction adds9products of two3-df bases. No multiplicity-adjusted or confirmatory significance claim.')
sx={(r['metric'],r['contrast']):r for r in read('sex_increment_contrasts')};data=[]
for target in ['prior_vs_current','sex_prior_vs_sex_current']:
 for group,label in [('1','Male'),('2','Female')]:data.append([contrast_labels[target],label,ci(vk['auc',group,target]),ci(vk['brier',group,target])])
 data.append([contrast_labels[target],'Female increment − male increment',ci(sx['auc',target],value='estimate'),ci(sx['brier',target],value='estimate')])
write('tableS15_sex_increments',['Added−reference comparison','Evaluation group or contrast','ΔAUC (95%CI)','ΔBrier (95%CI)'],data,['validation','sex_increment_contrasts'],'Models were fitted in the entire6307-person cohort and evaluated by sex, with common household resamples. Not separately trained sex-specific models. CI=confidence interval; AUC=area under the receiver operating characteristic curve. Direct differences are female increment−male increment, not subtraction of CI endpoints. NegativeBrier/positiveAUC favor added model. All intervals use new revision batch. These exploratory results do not establish equality, fairness or absence of effect modification. All5metrics are retained in sourceCSVs.')
cor=read('grip_correlation');trans=read('transitions');glabels={'all':'Overall','1':'Male','2':'Female'};tlabels={'total':'All transitions','not_low_to_not_low':'Not-low → not-low','not_low_to_low':'Not-low → low','low_to_not_low':'Low → not-low','low_to_low':'Low → low'};data=[['A:2010/2014Pearson correlation',glabels[r['group']],r['n_rounded_10'],num(r['pearson_r'],3)] for r in cor]+[['B:2010→2014strength category',tlabels[r['metric']],r['count_rounded_10'],'—'] for r in trans]
write('tableS16_correlation_transitions',['Summary','Group or transition','n, rounded','Pearson r'],data,['grip_correlation','transitions'],'Four-year Pearson correlation is not test–retest reliability. Low strength uses EWGSOP2 cutoffs: <27kg male,<16kg female; equality is not-low. These are low-strength categories, not healthy norms, sarcopenia diagnoses or weighted population prevalence. Counts rounded to tens; exact analytical N6307. A transition does not establish a causal effect.')
risk=read('oof_risk_change');labels={'weibull':'Weibull splines','neural':'Neural AFT','xgboost':'XGBoost AFT'};cl={'absolute':'Absolute change >2percentagepoints','increase':'Increase >2percentagepoints','decrease':'Decrease >2percentagepoints'};data=[]
for r in risk:
 val='SUPPRESSED' if r['proportion']=='NA' else ci(r,2,'proportion',100)
 data.append([labels[r['model']],cl[r['comparison']],r['count_rounded_10'],val])
write('tableS17_OOF_risk_changes',['Model','Prediction change','Count, rounded','Proportion%,95%CI'],data,['oof_risk_change','oof_replay_checks'],'OOF=out-of-fold; AFT=accelerated failure time; CI=confidence interval. Absolute probability threshold >0.02, not relative2%. Same6307real held-out participants; displayedn≈6310.5000paired household resamples condition on fixed predictions, folds,tuning and censoringweights; retraining/model-selection uncertainty omitted. Referenceerrors were within1e-8. When any linked numerator/complement is small, all3counts/proportions/CIs are jointly suppressed. Suppression does not identify which hidden cell triggered it. Prediction change is not improved accuracy, net benefit or an indication to change screening frequency.')
(O/'DISPLAY_TABLE_MANIFEST.json').write_text(json.dumps({'state':'REVISION_DISPLAY_VALUES','rounding':'Decimal ROUND_HALF_UP; absoluteperformance4,contrast5,percent2,mean/SD1,SMD3,r3; originalCSVstrings retained unmodified','tables':written,'limits':'Word tables display the same values with local formatting.'},ensure_ascii=False,indent=2)+'\n')
print('Generated7displayCSVs with',sum(r['row_count'] for r in written),'rows; unmodified sources remain in results/.')
